<template>
  <div class="main-layout">
    <header class="app-header">
      <button
        v-if="showBack"
        type="button"
        class="header-back"
        aria-label="Back"
        @click="goBack"
      >
        <span class="header-back-text">‹</span>
      </button>
      <span
        v-else
        class="header-spacer"
        :class="{ 'header-spacer--home': isDriverHome }"
      />
      <h1 class="header-title" :class="{ 'header-title--home': isDriverHome }">
        <span v-if="isDriverHome" class="title-with-icon">
          <i class="material-icons header-home-icon" aria-hidden="true">home</i>
          <span class="header-title-text">{{ title }}</span>
        </span>
        <template v-else>{{ title }}</template>
      </h1>
      <button
        v-if="showLogout"
        type="button"
        class="header-logout"
        aria-label="Log out"
        @click="onLogout"
      >
        <i class="material-icons">logout</i>
      </button>
      <span v-else class="header-spacer" />
    </header>
    <div class="main-body">
      <router-view />
    </div>
    <OrderRequestModal />
  </div>
</template>

<script>
import { mapActions } from 'vuex';
import OrderRequestModal from '../components/OrderRequestModal.vue';

export default {
  name: 'MainLayout',
  components: { OrderRequestModal },
  computed: {
    title() {
      return (this.$route.meta && this.$route.meta.title) || '';
    },
    showBack() {
      return !!(this.$route.meta && this.$route.meta.showBack);
    },
    showLogout() {
      return !!(this.$route.meta && this.$route.meta.showLogout);
    },
    isDriverHome() {
      return this.$route.name === 'DriverHome';
    },
  },
  methods: {
    ...mapActions('auth', ['logout']),
    goBack() {
      this.$router.push({ name: 'DriverHome' });
    },
    onLogout() {
      if (!window.confirm('Are you sure you want to logout?')) return;
      this.logout()
        .then(() => {
          this.$router.replace({ name: 'Login' });
        })
        .catch((err) => {
          window.alert(err.message || 'Failed to logout');
        });
    },
  },
};
</script>

