<template>
  <div
    v-if="currentOrder && showOrderModal"
    class="modal-overlay"
    @click.self="close"
  >
    <div class="modal-content">
      <h2 class="title">New Delivery Request</h2>

      <div class="divider" />

      <div class="order-info">
        <div class="info-row">
          <span class="label">Restaurant:</span>
          <p class="value">{{ currentOrder.restaurant_name }}</p>
        </div>

        <div class="info-row">
          <span class="label">Address:</span>
          <p class="value">{{ currentOrder.restaurant_address }}</p>
        </div>

        <div class="info-row">
          <span class="label">Delivery Price:</span>
          <p class="price">£{{ currentOrder.delivery_price }}</p>
        </div>
      </div>

      <div class="button-container">
        <button type="button" class="button reject-button" @click="reject">
          Reject
        </button>
        <button type="button" class="button accept-button" @click="accept">
          Accept
        </button>
      </div>
    </div>
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex';

export default {
  name: 'OrderRequestModal',
  computed: {
    ...mapState('notification', ['currentOrder', 'showOrderModal']),
  },
  methods: {
    ...mapActions('notification', ['acceptOrder', 'rejectOrder', 'setShowOrderModal']),
    accept() {
      this.acceptOrder();
    },
    reject() {
      this.rejectOrder();
    },
    close() {
      this.setShowOrderModal(false);
    },
  },
};
</script>

